import React from 'react';
import { Sidebar } from '../components/Dashboard/Sidebar';
import { ContextSidebar } from '../components/Dashboard/ContextSidebar';
import { ChatSession, Workspace, ContextItem } from '../types';

interface MainLayoutProps {
  children: React.ReactNode;
  // Workspaces
  workspaces: Workspace[];
  currentWorkspaceId: string | null;
  onSelectWorkspace: (id: string) => void;
  // Chats
  sessions: ChatSession[];
  currentSessionId: string | null;
  onNewChat: () => void;
  onSelectSession: (id: string) => void;
  onDeleteSession: (id: string, e: React.MouseEvent) => void;
  onRenameSession: (id: string, newTitle: string) => void;
  // Layout
  isSidebarOpen: boolean;
  onToggleSidebar: () => void;
  onLogout: () => void;
  onOpenSwitchModal: () => void;
  isDarkMode: boolean;
  onToggleTheme: () => void;
  isContextOpen: boolean;
  onToggleContext: () => void;
  // Context
  contextItems: ContextItem[];
  similarityThreshold: number;
  onUpdateThreshold: (val: number) => void;
  onRemoveContextItem: (id: string) => void;
  onToggleContextItemActive: (id: string) => void;
  // Extras
  currentModelName?: string;
  currentSessionTitle?: string;
}

export const MainLayout: React.FC<MainLayoutProps> = ({
  children,
  workspaces,
  currentWorkspaceId,
  onSelectWorkspace,
  sessions,
  currentSessionId,
  onNewChat,
  onSelectSession,
  onDeleteSession,
  onRenameSession,
  isSidebarOpen,
  onToggleSidebar,
  onLogout,
  onOpenSwitchModal,
  isDarkMode,
  onToggleTheme,
  isContextOpen,
  onToggleContext,
  contextItems,
  similarityThreshold,
  onUpdateThreshold,
  onRemoveContextItem,
  onToggleContextItemActive,
  currentModelName,
  currentSessionTitle
}) => {
  return (
    <div className="flex h-screen w-full overflow-hidden bg-white dark:bg-charcoal-950 transition-colors duration-300">
      <Sidebar
        workspaces={workspaces}
        currentWorkspaceId={currentWorkspaceId}
        onSelectWorkspace={onSelectWorkspace}
        sessions={sessions}
        currentSessionId={currentSessionId}
        onNewChat={onNewChat}
        onSelectSession={onSelectSession}
        onDeleteSession={onDeleteSession}
        onRenameSession={onRenameSession}
        isOpen={isSidebarOpen}
        onToggle={onToggleSidebar}
        onLogout={onLogout}
        onOpenSwitchModal={onOpenSwitchModal}
        isDarkMode={isDarkMode}
        onToggleTheme={onToggleTheme}
      />

      <div className="flex-1 flex flex-col min-w-0 bg-white dark:bg-charcoal-900 transition-colors duration-300 relative">
        {/* Top Navigation */}
        <header className="h-16 border-b border-gray-200 dark:border-charcoal-800 flex items-center justify-between px-6 shrink-0 bg-white/80 dark:bg-charcoal-900/80 backdrop-blur-md z-10">
          <div className="flex items-center gap-4 min-w-0">
             {!isSidebarOpen && (
                 <button 
                  onClick={onToggleSidebar}
                  className="p-2 hover:bg-gray-100 dark:hover:bg-charcoal-800 rounded-lg text-charcoal-500 transition-colors"
                 >
                    <div className="w-5 h-0.5 bg-current mb-1"></div>
                    <div className="w-5 h-0.5 bg-current mb-1"></div>
                    <div className="w-5 h-0.5 bg-current"></div>
                 </button>
             )}
             <div className="min-w-0">
                <h2 className="text-sm font-bold text-slate-800 dark:text-white truncate">
                    {currentSessionTitle || 'New Chat'}
                </h2>
                <div className="flex items-center gap-2">
                    <span className="text-[10px] text-accent-600 dark:text-accent-400 font-bold uppercase tracking-widest">{currentModelName || 'Select Model'}</span>
                </div>
             </div>
          </div>

          <div className="flex items-center gap-3">
              <button 
                onClick={onToggleContext}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${isContextOpen ? 'bg-accent-500 text-white shadow-lg shadow-accent-500/20' : 'bg-gray-100 dark:bg-charcoal-800 text-charcoal-500 hover:bg-gray-200 dark:hover:bg-charcoal-700'}`}
              >
                  {contextItems.filter(i => i.isActive !== false).length} Active Context
              </button>
          </div>
        </header>

        {/* Content Area */}
        <main className="flex-1 overflow-hidden flex flex-col relative">
          {children}
        </main>
      </div>

      <ContextSidebar
        isOpen={isContextOpen}
        contextItems={contextItems}
        similarityThreshold={similarityThreshold}
        onUpdateThreshold={onUpdateThreshold}
        onRemoveItem={onRemoveContextItem}
        onToggleActive={onToggleContextItemActive}
      />
    </div>
  );
};
